// Base64 Embedded Course Badge Icons
// Bypasses browser local file:// CORS restrictions and prevents canvas from becoming tainted!
const AI_BADGE_DATA = "data:image/png;base64,";
const EXCEL_BADGE_DATA = "data:image/png;base64,";
if (typeof window !== 'undefined') {
  window.AI_BADGE_DATA = AI_BADGE_DATA;
  window.EXCEL_BADGE_DATA = EXCEL_BADGE_DATA;
}